inp=dict(schema='primary67-complete-named-RAW-INPUT-payload-v1',complete_within_named_finite_inputs=True,boundary='Complete exact bytes of all named finite selected RAW/LF source regions and necessary existing66 statement contracts. Original whole-primary exact RAW/LF hashes are separately bound; no whole-paper inventory claim.',whole_primary_binding=regions['whole_primary'],inputs=[dict(pin=pin(f),encoding='base64-exact-RAW',complete_RAW_bytes_base64=base64.b64encode(f.read_bytes()).decode()) for f in selected],exact_source_region_maps=regions,primary_only_reuse_pins=read('primary-first-process.json')['prior_source_only_reuse'],necessary_existing66_reuse=read('finite-existing66-reuse-signatures.json'))
put('RAW-input-payload.json',inp)
decision=dict(schema='primary67-source-only-prerequisite-decision-v1',reviewer='/root/independent_source64',status='SOURCE_PRIMARY_PREREQUISITES_FROZEN',source_candidate_verdict=None,no_candidate67_or_header67_seen=True,semantic_slots=slots['semantic_slots'],deltas=[],repairs=[],source_mathematical_repair=False,source_first=True,source_graph_independent_of_Lean=True,source_coverage=dict(regions=6,classified=344,missing=0,missing_alttext=0,missing_annotation=0,annotation_mismatch=0,exact_reused_primary66_items=310,new_B3_items=34,classification_counts=inventory['classification_counts']),source_graph_RAW_pin=pin(O/'source-proof-graph.json'),source_inventory_RAW_pin=pin(O/'source-coverage-inventory.json'),literal_formulas_and_conditions=read('literal-formulas-and-conditions.json'),next_statement_boundary=residual,proof_search=False,compiler_run=False,SAU_claim=False,Goal_claim=False,canonical_writes=False,mathematical_completion_claim=False,full_Exposition=False,PURIFIED=False)
analytical=['first-primary-read.json','primary-first-process.json','source-input-regions.json','source-proof-graph.json','source-coverage-inventory.json','classification-refinement.json','finite-existing66-reuse-signatures.json','literal-formulas-and-conditions.json','residual-next-header.json','seven-source-semantic-slots.json']
run=dict(schema='primary67-complete-logical-review-run-v1',reviewer='/root/independent_source64',actual_finalizer_pid=os.getpid(),finalized_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),complete_source_decision=decision,complete_named_RAW_INPUT_payload=inp,source_evidence={n:read(n) for n in analytical},preserved_negatives={f.name:json.loads(f.read_bytes()) for f in sorted(O.glob('negative.*.json'))},owned_pre_finalization_RAW_LF_bindings=[pin(f) for f in sorted(O.iterdir()) if f.is_file()],closure_contract=dict(logical_hash='Canonical UTF8 JSON of ENTIRE object deleting ONLY top-level run_sha256; ensure_ascii=false,sort_keys=true,separators comma colon',COMPLETE_RAW_REVIEW='review-run.json exact full bytes, no deletion/projection, includes all7 source slots and complete next-boundary decision',COMPLETE_RAW_DECISION='primary-source-decision.json exact full bytes, all7 slots and entire source prerequisite decision; external run hash added after logical sealing',SEPARATE_COMPLETE_RAW_INPUT='RAW-input-payload.json exact full finite named RAW input bytes and whole-source bindings, distinct from review/decision',terminal_and_self_binding='Exhaustive final owned manifest covers all files including negatives/scripts/input/outputs/foreground receipts; manifest RAW pinned by CLOSED_LAST final lease, lease externally RAW pinned at read-only postclose',no_circular_self_hash_claim=True),no_candidate67_verdict=True,no_mathematical_completion_claim=True)
